// Randomizer seeds (generated by LAS-Randomizer through tools/rando/las_headless.py).
//
// A seed lives in rando/<name>/: romfs/ (replacement game files), exefs/1.0.0.pchtxt (code/data patches),
// settings.json, spoiler log, and save/ (this seed's own save slots). The active seed is chosen in the menu
// (larecomp.ini `rando_seed`); switching reboots the game in place (runtime/main.c), which calls rando_boot.
//
// Code patches: gen.py compiled every variant of every patched instruction in (tools/rando/patch_variants.json);
// rando_word() tells the generated code which one the seed uses (0 = the original instruction).
#include "rando.h"
#include "game_addresses.h"

#include <dirent.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "hle.h"
#include "settings.h"
#include "gameversion.h"
#include "rando_profile.h"

#define MAIN_BASE 0x7000000000ull
#define WORD_TAB 256

static struct { uint64_t addr; uint32_t word; } words[WORD_TAB];
static int nwords;
static char g_seed_dir[512];
static bool g_active;
static int g_inited;
static pthread_mutex_t g_init_lock = PTHREAD_MUTEX_INITIALIZER;

void rando_init(void);
const char *rando_seed_dir(void) {
    rando_init();  // (lazy: callers can run before anything else touched the seed, e.g. the launch movie)
    return g_active ? g_seed_dir : NULL;
}

static void apply_data(uint64_t img_off, const uint8_t *bytes, size_t n) {
    uint8_t *p = (uint8_t *)(uintptr_t)(MAIN_BASE + img_off);
    uintptr_t page = (uintptr_t)p & ~0x3FFFull;
    plat_protect(page, ((uintptr_t)p + n - page + 0x3FFF) & ~0x3FFFull, PLAT_PROT_RW);
    memcpy(p, bytes, n);
}

static bool load_pchtxt(const char *path) {
    RandoPatchSet patches;
    char why[256];
    if (!rando_patch_read(path, game_version_current(), &patches, why, sizeof why)) {
        LOG("[rando] rejected seed: %s\n", why);
        return false;
    }
    for (int i = 0; i < patches.code_count; ++i) {
        words[nwords].addr = game_main_address(MAIN_BASE + patches.code[i].offset);
        words[nwords++].word = patches.code[i].word;
    }
    for (int i = 0; i < patches.data_count; ++i)
        apply_data(patches.data[i].offset, patches.data[i].bytes, patches.data[i].size);
    LOG("[rando] %d validated code words, %d data patches from %s\n", nwords, patches.data_count, path);
    return true;
}

static bool init(void) {
    settings_load();
    const char *seed = getenv("LARECOMP_RANDO_SEED") ? getenv("LARECOMP_RANDO_SEED") : g_settings.rando_seed;
    if (!seed || !seed[0]) return true;
    if (!rando_seed_name_valid(seed)) { LOG("[rando] invalid seed name\n"); return false; }
    snprintf(g_seed_dir, sizeof g_seed_dir, "rando/%s", seed);
    struct stat sb;
    if (stat(g_seed_dir, &sb) || !S_ISDIR(sb.st_mode)) { LOG("[rando] seed folder %s missing\n", g_seed_dir); return false; }
    if (!rando_seed_compatible(g_seed_dir, game_version_current())) {
        LOG("[rando] seed belongs to another game version\n"); return false;
    }
    char p[600];
    snprintf(p, sizeof p, "%s/exefs/%s", g_seed_dir, rando_patch_filename(game_version_current()));
    if (!load_pchtxt(p)) return false;
    g_active = true;
    LOG("[rando] seed \"%s\" active\n", seed);
    return true;
}

void rando_init(void) {
    if (__atomic_load_n(&g_inited, __ATOMIC_ACQUIRE)) return;
    pthread_mutex_lock(&g_init_lock);
    if (!g_inited) { init(); __atomic_store_n(&g_inited, 1, __ATOMIC_RELEASE); }
    pthread_mutex_unlock(&g_init_lock);
}

// Each boot, right after the modules are loaded (runtime/main.c): the chosen seed (it may have changed since the
// last boot) and its data patches, into the freshly loaded module.
bool rando_boot(void) {
    pthread_mutex_lock(&g_init_lock);
    nwords = 0;
    g_active = false;
    g_seed_dir[0] = 0;
    bool ok = init();
    __atomic_store_n(&g_inited, 1, __ATOMIC_RELEASE);
    pthread_mutex_unlock(&g_init_lock);
    return ok;
}

// Pick the seed for the next boot ("" = vanilla) and remember it (larecomp.ini); a choice made in the game wins over
// LARECOMP_RANDO_SEED (test runs).
void rando_select(const char *seed) {
    strlcpy(g_settings.rando_seed, seed ? seed : "", sizeof g_settings.rando_seed);
    settings_save();
    unsetenv("LARECOMP_RANDO_SEED");
}

uint32_t rando_word(uint64_t addr) {
    rando_init();
    for (int i = 0; i < nwords; i++)
        if (words[i].addr == addr) return words[i].word;
    return 0;
}

// Host path of a seed's replacement for romfs file `path` (relative, e.g. "region_common/event/Tarin.bfevfl").
bool rando_romfs_override(const char *path, char *out, size_t cap) {
    rando_init();
    if (!g_active) return false;
    snprintf(out, cap, "%s/romfs/%s", g_seed_dir, path);
    struct stat sb;
    return stat(out, &sb) == 0 && S_ISREG(sb.st_mode);
}

// Items page: hide the item explanation text in randomizer seeds (tools/patches.py ITEM_EXPLANATION_SITE); it
// overlaps the inventory overlay's dungeon-key / trade rows and the player knows the items.
int rt_hide_item_explanation(void) {
    static int env = -1;  // LARECOMP_SHOW_ITEM_TEXT=1 keeps it
    if (env < 0) env = getenv("LARECOMP_SHOW_ITEM_TEXT") != NULL;
    return !env && rando_seed_dir() != NULL;
}
